import{_ as o,o as e,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Набор модов сервера","description":"","frontmatter":{"pageId":"players/modpacks","contentRevision":2},"headers":[],"relativePath":"ru/players/modpacks.md","filePath":"ru/players/modpacks.md"}'),l={name:"ru/players/modpacks.md"};function t(s,a,n,d,p,h){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="набор-модов-сервера" tabindex="-1">Набор модов сервера <a class="header-anchor" href="#набор-модов-сервера" aria-label="Permalink to &quot;Набор модов сервера&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Окно различий сравнивает требования сервера с установленными модами и порядком загрузки. Сначала прочитай список несовпадений. Сервер может требовать точные файлы и общие настройки, а не только одинаковое название мода.</p><p>Если доступна серверная доставка, выбери предложенный пакет и проверь сведения о нём. Загрузка и применение разделены: игра должна быть закрыта для замены используемых файлов. После применения перезапусти игру и повтори проверку. Не накладывай вручную случайную версию Workshop поверх уже проверенного пакета.</p><p>Без опубликованного архива установи требования по инструкциям администратора. Сохрани резервную копию своей конфигурации перед заменой настроек.</p><h3 id="workshop-исправление-различии" tabindex="-1">Workshop: исправление различий <a class="header-anchor" href="#workshop-исправление-различии" aria-label="Permalink to &quot;Workshop: исправление различий&quot;">​</a></h3><ol><li>Прочитай категории: отсутствующие моды, версии, изменённые файлы, запрещённые моды, порядок и общие настройки. Если твоя версия новее, может потребоваться обновление сервера; клиент не умеет получать произвольную старую ревизию Workshop.</li><li>Нажми <strong>Исправить и перезапустить</strong> (<strong>Fix and restart</strong>). Клиент подпишется на недостающие Workshop-моды, дождётся Steam, упорядочит список, отключит запрещённые дополнения и подготовит общие настройки. Старый список сохранится в <code>Config/ModsConfig.rimlink-backup.xml</code>.</li><li>После перезапуска Rimlink продолжит подключение. Парольная учётная запись снова запросит пароль: он не сохраняется. Если файлы всё ещё различаются, передай подробности администратору, а не обходи сверку.</li><li>Серверные настройки действуют и при следующих запусках, в том числе в одиночной игре. Чтобы вернуть личные, нажми в главном меню действие <strong>Настройки модов [сервера] действуют: использовать мои</strong> и перезапусти игру. Личные файлы настроек не перезаписываются.</li></ol><h3 id="серверныи-архив-загрузка-проверка-восстановление" tabindex="-1">Серверный архив: загрузка, проверка, восстановление <a class="header-anchor" href="#серверныи-архив-загрузка-проверка-восстановление" aria-label="Permalink to &quot;Серверный архив: загрузка, проверка, восстановление&quot;">​</a></h3><ol><li>Рядом с сохранённым сервером выбери <strong>Скачать набор модов сервера</strong> или действие в окне различий. Проверь сертификат до ввода серверного пароля. Просмотри моды, размеры архива/распаковки и действия установки/повторного использования; отдельно подтверди доверие к коду и общим настройкам.</li><li>Дождись возобновляемой загрузки и проверки SHA-256, путей и размеров. Новые моды попадут в отдельные <code>Mods/rimlink-managed-…</code>. Точная установленная копия может использоваться повторно; отличающиеся или дублирующиеся неуправляемые копии блокируют установку с указанием путей и не перезаписываются. Лишние игровые моды отключаются, но не удаляются.</li><li>Полный снимок настроек подготавливается до одного перезапуска. Для подтверждения установки нужны совпадающие загруженные моды/настройки и успешный вход. При сбое файлы и копии сохраняются для повторной попытки без цикла перезапусков.</li><li>После прерывания выбери <strong>Откатить установку</strong> в списке серверов для незавершённого журнала. Сохрани <code>Rimlink/install-journal.json</code>, маркер незавершённой установки и копии. Внешние изменения останавливают автоматическое восстановление: разбирай указанные файлы вручную с закрытой игрой. Загруженные сборки нельзя безопасно заменить или восстановить.</li></ol><h2 id="modpack-decision" tabindex="-1">Выбор пути: Workshop или серверный пакет? <a class="header-anchor" href="#modpack-decision" aria-label="Permalink to &quot;Выбор пути: Workshop или серверный пакет? {#modpack-decision}&quot;">​</a></h2><p>Если сервер опубликовал только требования, клиенту нужны собственные копии обязательных модов и DLC. «Fix and restart» может оформить подписки Workshop и порядок, но не создаёт отсутствующую старую версию мода. Если сервер предлагает доставку, он должен иметь право распространять код каждого включённого мода.</p><p>Сначала прочти diff: «отсутствует», «версия новее серверной», «файлы изменены» и «настройки отличаются» требуют разных действий. Если mismatch остаётся после повторной загрузки Workshop, передай список администратору. Не выключай проверку, не копируй случайные DLL, не подменяй manifest.</p><p>Перед применением серверного пакета проверь адрес, сертификат, размеры и список кода. Согласие на общие настройки отдельно от установки кода. Собственная сохранённая игра тоже может использовать активный серверный набор настроек, пока ты явно не вернёшь личные.</p><h2 id="modpack-recovery" tabindex="-1">Безопасное восстановление после прерванной установки <a class="header-anchor" href="#modpack-recovery" aria-label="Permalink to &quot;Безопасное восстановление после прерванной установки {#modpack-recovery}&quot;">​</a></h2><p>Разделяй скачивание, проверку, применение и загрузку после перезапуска. Незавершённое скачивание не значит, что коллекция уже установлена. Внешне изменённый unmanaged-мод не должен молча заменяться: диалог показывает конфликтный путь.</p><p>Сохрани install-journal, pending marker и резервные копии. Для незавершённой установки используй «Roll back installation» в списке серверов. Если файлы после установки изменялись внешними средствами, автоматический откат может остановиться: закрой игру, сверяй указанные пути и не удаляй весь каталог Mods. Загруженные сборки нельзя надёжно откатить в работающей игре.</p><p>После восстановления перезапусти игру, повторно пройди сверку и проверь личные/серверные настройки. Только успешный повторный вход с нужными загруженными модами завершает проверку.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Игра, Core и DLC не входят в пакет. Доступность загрузчика без Steam не доказывает проверенную работу GOG. При несовпадении hash не обходи проверку редактированием манифеста.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../compatibility">Версии и совместимость</a></li><li><a href="./../admins/modpacks">Управление набором модов</a></li><li><a href="./install">Установка мода</a></li></ul>',22)])])}const k=o(l,[["render",t]]);export{m as __pageData,k as default};
